  AssetColorEffect opponentColorEffect = AssetColorEffect::None;
  uint16_t playerBlendColor = TFT_WHITE;
  uint16_t opponentBlendColor = TFT_WHITE;
  uint8_t playerBlendAmount = 0;
  uint8_t opponentBlendAmount = 0;
  // Rapid Spin's elevation helper is a scanline reveal/hide in FireRed, not
  // a squash or vertical translation. Keep a source-row clip for each
  // battler so the retained renderer can reproduce it without moving the mon.
  uint8_t playerClipTop = 0;
  uint8_t playerClipBottom = 64;
  uint8_t opponentClipTop = 0;
  uint8_t opponentClipBottom = 64;
  bool hidePlayer = false;
  bool hideOpponent = false;
  // Cmd_monbg temporarily moves a battler from OBJ to a battle BG so effect
  // sprites can cross in front of it.  Preserve that depth state in the
  // retained compositor instead of parsing the command and discarding it.
  bool playerInBackgroundLayer = false;
  bool opponentInBackgroundLayer = false;
  bool metallic = false;
  uint8_t metallicPhase = 0;
  int16_t metallicX = 0;
  int16_t metallicY = 0;
  char metallicPath[96]{};
  char backgroundPath[96]{};
  int16_t backgroundOffsetX = 0;
  int16_t backgroundOffsetY = 0;
  uint8_t backgroundPaletteFirst = 0;
  uint8_t backgroundPaletteCount = 0;
  uint8_t backgroundPaletteShift = 0;
  bool backgroundWrap = false;
  bool backgroundNativeCamera = false;
  // Geometry belongs to the retained plane itself.  Keeping the virtual
  // extent here avoids consulting a separate "last rendered background"
  // variable while composing the current frame (which made the first
  // Fissure frame use the wrong 256px wrap width).
  uint16_t backgroundVirtualWidth = 0;
  uint16_t backgroundVirtualHeight = 0;
  uint8_t backgroundVirtualFillIndex = 0xFFU;
  BattleFieldAsset fieldAsset = BattleFieldAsset::None;
  int16_t fieldDestinationX = 0;
  int16_t fieldDestinationY = 0;
  int16_t fieldOffsetX = 0;
  int16_t fieldOffsetY = 0;
  uint8_t fieldOpacity = 0;
  uint8_t fieldPaletteFirst = 0;
  uint8_t fieldPaletteCount = 0;
  uint8_t fieldPaletteShift = 0;
  uint16_t fieldWidth = 320;
  uint16_t fieldHeight = 184;
  bool fieldWrap = true;
  bool fieldWrapX = true;
  bool fieldWrapY = true;
  bool fieldNativeCamera = false;
  bool cursePlayer = false;
  bool curseOpponent = false;
  int16_t curseOffsetY = 0;
  bool curePlayer = false;
  bool cureOpponent = false;
  int16_t cureOffsetX = 0;
  int16_t cureOffsetY = 0;
  uint8_t arenaFadeToBlack = 0;
  // FireRed palette callbacks can address the whole battle palette, not just
