void normalizeSettings() {
  gameSave.settings.homeBackground = HomeBackgrounds::normalize(gameSave.settings.homeBackground);
  gameSave.settings.setColorTheme(gameSave.settings.colorTheme());
  if (gameSave.settings.brightnessPercent < 20 || gameSave.settings.brightnessPercent > 100)
    gameSave.settings.brightnessPercent = 80;
  gameSave.settings.brightnessPercent = static_cast<uint8_t>((gameSave.settings.brightnessPercent / 20U) * 20U);
  if (gameSave.settings.screenTimeout() >= kScreenTimeoutCount)
    gameSave.settings.setScreenTimeout(1);
}

const char* screenTimeoutLabel(uint8_t index) {
  static constexpr const char* labels[kScreenTimeoutCount] = {"1 MIN", "2 MIN", "5 MIN", "10 MIN"};
  return labels[index < kScreenTimeoutCount ? index : 1];
}

bool inside(const TouchPoint& p, int16_t x, int16_t y, int16_t w, int16_t h) {
  // Keep hit boxes almost identical to their painted bounds. Expanding every
  // control by five pixels made neighbouring FireRed controls overlap and a
  // physically correct tap could be claimed by the wrong button.
  constexpr int16_t kTouchTolerance = 3;
  return p.x >= x - kTouchTolerance && p.x < x + w + kTouchTolerance &&
         p.y >= y - kTouchTolerance && p.y < y + h + kTouchTolerance;
}

// Generation III derives gender from the low personality byte and the
// species threshold. Keep it presentation-only: the same immutable
// personality already drives Attract and remains persisted in every save.
int8_t displayedPokemonGender(const OwnedPokemon& pokemon) {
  const SpeciesData* species = findSpecies(pokemon.speciesId);
  if (!species || species->genderRatio == 255U) return -1;  // genderless
  if (species->genderRatio == 0U) return 0;                 // male
  if (species->genderRatio == 254U) return 1;               // female
  return static_cast<uint8_t>(pokemon.personality & 0xFFU) < species->genderRatio ? 1 : 0;
}

// FireRed's font table stores gender as dedicated control glyphs rather than
// normal text. Draw their tiny pixel geometry directly so no '?' placeholder
// appears and the symbols stay legible on the 2.8-inch panel.
void drawPokemonGenderSymbol(const OwnedPokemon& pokemon, int16_t centerX, int16_t centerY) {
  const int8_t gender = displayedPokemonGender(pokemon);
  if (gender < 0) return;
  const uint16_t color = gender == 1 ? TFT_RED : TFT_BLUE;
  display.drawCircle(centerX, centerY, 3, color);
  display.drawCircle(centerX, centerY, 2, color);
  if (gender == 1) {
    display.drawFastVLine(centerX, centerY + 3, 5, color);
    display.drawFastHLine(centerX - 2, centerY + 6, 5, color);
  } else {
    display.drawLine(centerX + 2, centerY - 2, centerX + 6, centerY - 6, color);
    display.drawFastHLine(centerX + 3, centerY - 6, 4, color);
    display.drawFastVLine(centerX + 6, centerY - 6, 4, color);
  }
}

void button(int16_t x, int16_t y, int16_t w, int16_t h, const char* label, uint16_t color) {
  display.fillRoundRect(x, y, w, h, 6, color); display.drawRoundRect(x, y, w, h, 6, TFT_WHITE);
  // The asset-derived FireRed font has no '<' or '>' glyphs. Keep navigation
  // controls graphical everywhere (Bag, Trainer Card and Settings) instead
  // of rendering a misleading question mark on the real display.
  if (label && std::strcmp(label, "<") == 0) {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + w / 2 - 8, cy, x + w / 2 + 6, cy - 8,
                         x + w / 2 + 6, cy + 8, TFT_WHITE);
    return;
  }
  if (label && std::strcmp(label, ">") == 0) {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + w / 2 + 8, cy, x + w / 2 - 6, cy - 8,
                         x + w / 2 - 6, cy + 8, TFT_WHITE);
    return;
  }
  if (label && std::strcmp(label, "< PREV") == 0) {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + 8, cy, x + 20, cy - 7, x + 20, cy + 7, TFT_WHITE);
    fireRedText.setTextColor(TFT_WHITE, color); fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawString("PREV", x + w / 2 + 8, cy, 1); fireRedText.setTextDatum(TL_DATUM);
    return;
  }
  if (label && std::strcmp(label, "NEXT >") == 0) {
    const int16_t cy = y + h / 2;
    display.fillTriangle(x + w - 8, cy, x + w - 20, cy - 7, x + w - 20, cy + 7, TFT_WHITE);
    fireRedText.setTextColor(TFT_WHITE, color); fireRedText.setTextDatum(MC_DATUM);
    fireRedText.drawString("NEXT", x + w / 2 - 8, cy, 1); fireRedText.setTextDatum(TL_DATUM);
    return;
  }
  fireRedText.setTextColor(TFT_WHITE, color); fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawStringFitted(label, x + w / 2, y + h / 2,
                               std::max<int16_t>(1, w - 4), 2);
  fireRedText.setTextDatum(TL_DATUM);
}

void outlinedButtonLabel(const char* label, int16_t centerX, int16_t centerY,
                         int16_t maxWidth, uint16_t foreground = TFT_WHITE) {
  if (!label || !label[0]) return;
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.setTextColor(TFT_BLACK);
  for (int8_t offsetY = -1; offsetY <= 1; ++offsetY) {
    for (int8_t offsetX = -1; offsetX <= 1; ++offsetX) {
      if (!offsetX && !offsetY) continue;
      fireRedText.drawStringFitted(label, centerX + offsetX, centerY + offsetY,
                                   std::max<int16_t>(1, maxWidth - 2), 2);
    }
  }
  fireRedText.setTextColor(foreground);
  fireRedText.drawStringFitted(label, centerX, centerY,
                               std::max<int16_t>(1, maxWidth - 2), 2);
  fireRedText.setTextDatum(TL_DATUM);
}

void bar(int16_t x, int16_t y, const char* label, uint16_t value, uint16_t maximum, uint16_t color) {
  fireRedText.setTextColor(TFT_WHITE, TFT_BLACK); fireRedText.drawStringFitted(label, x, y, 40, 1);
  display.drawRect(x + 42, y, 94, 9, TFT_DARKGREY);
  const uint16_t width = maximum ? static_cast<uint16_t>(88U * value / maximum) : 0;
  display.fillRect(x + 45, y + 2, width, 5, color);
}

uint16_t speciesColor(uint16_t id) {
  if (id == 1 || id == 10) return TFT_GREEN;
  if (id == 4) return TFT_ORANGE;
  if (id == 7) return TFT_CYAN;
  if (id == 13) return TFT_YELLOW;
  if (id == 16) return TFT_LIGHTGREY;
  return TFT_MAGENTA;
}

enum class PokemonAssetView : uint8_t { Front, Back, Icon };

void pokemonAssetPath(char* path, size_t size, const OwnedPokemon& pokemon,
                      PokemonAssetView view, uint8_t frame = 0,
                      uint16_t displayedSpecies = 0) {
  const uint16_t species = displayedSpecies ? displayedSpecies : pokemon.speciesId;
  const char* shiny = pokemon.shiny ? "shiny/" : "";
  const MegaVariant mega=MegaEvolution::variantFor(pokemon);
  if(mega!=MegaVariant::None&&species==pokemon.speciesId){
    const MegaFormData* megaForm=MegaEvolution::formData(species,mega);
    if(megaForm){
      if(view==PokemonAssetView::Icon)
        std::snprintf(path,size,"/pokegochi/assets/pokemon/forms/mega/%03u/%s/%sicons/%u.pkg",
                      species,megaForm->assetVariant,shiny,static_cast<unsigned>(frame&1U));
      else
        std::snprintf(path,size,"/pokegochi/assets/pokemon/forms/mega/%03u/%s/%s%s.pkg",
                      species,megaForm->assetVariant,shiny,
                      view==PokemonAssetView::Back?"back":"front");
      return;
    }
  }
  // A real Unown is tied to its personality-derived form. If another species
  // is merely being presented as Unown through Transform, BattleEngine has
  // copied the target's explicit form byte into that battler as well.
  if (species == 201) {
    const uint8_t form = std::min<uint8_t>(pokemon.form, 27U);
    if (view == PokemonAssetView::Icon)
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/unown/%02u/%sicons/%u.pkg",
                    form, shiny, static_cast<unsigned>(frame & 1U));
    else
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/unown/%02u/%s%s.pkg",
                    form, shiny, view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (species == 386) {
    const uint8_t form = std::min<uint8_t>(pokemon.form, 3U);
    if (view == PokemonAssetView::Icon)
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/deoxys/%u/%sicons/%u.pkg",
                    form, shiny, static_cast<unsigned>(frame & 1U));
    else
      std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/deoxys/%u/%s%s.pkg",
                    form, shiny, view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (species == 351 && view != PokemonAssetView::Icon && pokemon.form) {
    const uint8_t form = std::min<uint8_t>(pokemon.form, 3U);
    std::snprintf(path, size, "/pokegochi/assets/pokemon/forms/castform/%u/%s%s.pkg",
                  form, shiny, view == PokemonAssetView::Back ? "back" : "front");
    return;
  }
  if (view == PokemonAssetView::Icon)
    std::snprintf(path, size, "/pokegochi/assets/pokemon/%sicons/%03u_%u.pkg",
                  shiny, species, static_cast<unsigned>(frame & 1U));
  else
    std::snprintf(path, size, "/pokegochi/assets/pokemon/%s%s/%03u.pkg", shiny,
                  view == PokemonAssetView::Back ? "back" : "front", species);
}

void creature(int16_t x, int16_t y, const OwnedPokemon& pokemon, bool wild = false,
              uint16_t displayedSpecies = 0) {
  const uint16_t speciesId=displayedSpecies?displayedSpecies:pokemon.speciesId;
  if (sdReady && speciesId >= 1 && speciesId <= 386) {
    char path[112]; pokemonAssetPath(path, sizeof(path), pokemon,
        wild ? PokemonAssetView::Front : PokemonAssetView::Icon, iconFrame,
        displayedSpecies);
    const int16_t size = wild ? 64 : 32;
    if (AssetRenderer::draw(display, path, x - size / 2, y - size / 2)) return;
  }
  const uint16_t color = speciesColor(speciesId);
  display.fillCircle(x, y, wild ? 24 : 34, color);
  display.fillTriangle(x - 24, y - 18, x - 15, y - 37, x - 8, y - 17, color);
  display.fillTriangle(x + 8, y - 17, x + 17, y - 37, x + 24, y - 18, color);
  display.fillCircle(x - 10, y - 4, 3, TFT_BLACK); display.fillCircle(x + 10, y - 4, 3, TFT_BLACK);
}

void creature(int16_t x, int16_t y, uint16_t speciesId, bool wild = false,
              bool shiny = false, uint8_t form = 0) {
  OwnedPokemon visual{};visual.speciesId=speciesId;visual.shiny=shiny;visual.form=form;
  creature(x,y,visual,wild);
}

void battleBackSprite(int16_t x, int16_t y, const OwnedPokemon& pokemon,
                      uint16_t displayedSpecies = 0) {
  const uint16_t speciesId=displayedSpecies?displayedSpecies:pokemon.speciesId;
  if (sdReady && speciesId >= 1 && speciesId <= 386) {
    char path[112]; pokemonAssetPath(path, sizeof(path), pokemon,
                                     PokemonAssetView::Back,0,displayedSpecies);
    if (AssetRenderer::draw(display, path, x - 32, y - 32)) return;
  }
  creature(x,y,pokemon,true,displayedSpecies);
}

