        const uint8_t opacity = static_cast<uint8_t>(std::min<uint16_t>(9U,
            fadeAge / 3U));
        const uint16_t shrinkAge = task.age > 27U + hold
            ? static_cast<uint16_t>(task.age - 27U - hold) : 0U;
        const int16_t matrix = static_cast<int16_t>(128 + shrinkAge * 8U);
