        uint16_t color = gbaBattleColorToRgb565(0x7FFF);
        const char* terrain = chooseBattleTerrain(presentedBattleOpponent());
        if (std::strcmp(terrain, "grass") == 0) color = gbaBattleColorToRgb565(0x0B0C);
        else if (std::strcmp(terrain, "longgrass") == 0) color = gbaBattleColorToRgb565(0x09E0);
        else if (std::strcmp(terrain, "sand") == 0) color = gbaBattleColorToRgb565(0x2F1E);
        else if (std::strcmp(terrain, "underwater") == 0) color = gbaBattleColorToRgb565(0x4800);
        else if (std::strcmp(terrain, "water") == 0 || std::strcmp(terrain, "pond") == 0)
          color = gbaBattleColorToRgb565(0x7ECB);
        else if (std::strcmp(terrain, "mountain") == 0) color = gbaBattleColorToRgb565(0x2A16);
        else if (std::strcmp(terrain, "cave") == 0) color = gbaBattleColorToRgb565(0x0D2E);
        applyColor(attackerOpponent, AssetColorEffect::Blend, color, amount);
