uint16_t evolutionFromSpecies = 0, evolutionToSpecies = 0, evolutionVisibleSpecies = 0;
uint8_t evolutionVisualStage = 0; // 0=intro, 1=cycle, 2=flash, 3=complete
bool evolutionShiny = false, evolutionLightSilhouette = false;
bool evolutionCancelPromptVisible = false;
bool evolutionCanceledMessageVisible = false;
bool evolutionTouchLatched = true;
uint16_t eggHatchSpecies = 0;
uint8_t eggHatchVisualStage = 0; // 0=fresh, 1=cracked, 2..4=breaking, 5=shell, 6=reveal
int8_t eggHatchRockOffset = 0;
bool eggHatchShiny = false;
uint8_t eggHatchLevel = 5;
// All evolution sprites are exported on the same 64x64 canvas. Keep the
// particle geometry anchored to that canvas instead of to unrelated absolute
// screen coordinates; otherwise the sparkle ring sits visibly below the mon.
constexpr int16_t kEvolutionSpriteX = 128;
// The 160 px FireRed scene becomes 213 px high on this display, placing its
// visual centre at y=106. Keep the 64 px Pokemon canvas on that exact centre.
constexpr int16_t kEvolutionSpriteY = 74;
constexpr int16_t kEvolutionSpriteSize = 64;
constexpr int16_t kEvolutionCenterX = kEvolutionSpriteX + kEvolutionSpriteSize / 2;
constexpr int16_t kEvolutionCenterY = kEvolutionSpriteY + kEvolutionSpriteSize / 2;

OwnedPokemon tradeOutgoingVisual{};
OwnedPokemon tradeIncomingVisual{};
uint8_t tradeVisualStage = 0;
uint8_t tradeBallFrame = 0;
int16_t tradeVisualY = 92;
int16_t tradeBallX = 152;

void drawEvolutionCinematic() {
  display.fillScreen(themeDark());
  AssetRenderer::draw(display, "/pokegochi/assets/firered/evolution_scene/scene.pkg", 0, 0);
  char spritePath[96];
  if (evolutionVisualStage == 1 || evolutionVisualStage == 2) {
    std::snprintf(spritePath, sizeof(spritePath), "/pokegochi/assets/pokemon/evolution/%s/%03u.pkg",
                  evolutionLightSilhouette ? "light" : "dark", evolutionVisibleSpecies);
  } else {
    std::snprintf(spritePath, sizeof(spritePath), "/pokegochi/assets/pokemon/%sfront/%03u.pkg",
                  evolutionShiny ? "shiny/" : "", evolutionVisibleSpecies);
  }
  AssetRenderer::draw(display, spritePath, kEvolutionSpriteX, kEvolutionSpriteY);

  if (evolutionVisualStage == 1 || evolutionVisualStage == 2) {
    // Top-left offsets include the 4 px centre of the original 8x8 FireRed
    // sparkle. Their average stays within one pixel of the Pokemon centre.
    static constexpr int16_t kSparkles[][2] = {
      {-44,-1},{-33,-27},{-14,-42},{10,-38},{29,-20},{35,4},{21,25},{-6,35},{-32,25}
    };
    const uint8_t count = evolutionVisualStage == 2 ? 9U : 4U;
    for (uint8_t index = 0; index < count; ++index)
      AssetRenderer::draw(display, "/pokegochi/assets/firered/evolution_scene/sparkle.pkg",
                          kEvolutionCenterX + kSparkles[index][0],
                          kEvolutionCenterY + kSparkles[index][1]);
  }

  drawFireRedBattleWindow(4, 183, 312, 53, themeAccent(), TFT_WHITE);
  const SpeciesData* before = findSpecies(evolutionFromSpecies);
  const SpeciesData* after = findSpecies(evolutionToSpecies);
  char line[64];
  if (evolutionCanceledMessageVisible) {
    std::snprintf(line, sizeof(line), "HUH? %s STOPPED EVOLVING!",
                  before ? before->name : "POKEMON");
  } else if (evolutionVisualStage < 3) {
    std::snprintf(line, sizeof(line), "WHAT? %s IS EVOLVING!", before ? before->name : "POKEMON");
  } else {
    std::snprintf(line, sizeof(line), "CONGRATULATIONS! YOUR %s", before ? before->name : "POKEMON");
  }
  fireRedText.setTextColor(TFT_DARKGREY, TFT_WHITE);
  fireRedText.drawStringFitted(line, 15, 193, 290, 2);
  if (evolutionVisualStage == 3 && !evolutionCanceledMessageVisible) {
    std::snprintf(line, sizeof(line), "EVOLVED INTO %s!", after ? after->name : "A NEW FORM");
    fireRedText.drawStringFitted(line, 15, 214, 290, 2);
  }

  // FireRed cancels an evolution with B. On the touch-only Pokegochi the
  // small top-left X is the equivalent, with a deliberately larger invisible
  // hit target so it remains comfortable on a resistive 2.8-inch panel.
  if (evolutionVisualStage < 3 && !evolutionCanceledMessageVisible) {
    drawFireRedBattleWindow(7, 7, 28, 28, themeAccent(), TFT_WHITE);
    display.drawLine(15, 15, 27, 27, themeDark());
    display.drawLine(27, 15, 15, 27, themeDark());
    display.drawLine(16, 15, 28, 27, themeDark());
    display.drawLine(28, 15, 16, 27, themeDark());
  }

  if (evolutionCancelPromptVisible) {
    drawFireRedBattleWindow(63, 61, 194, 112, themeAccent(), TFT_WHITE);
    fireRedText.setTextDatum(MC_DATUM);
    fireRedText.setTextColor(themeDark(), TFT_WHITE);
    fireRedText.drawString("STOP EVOLUTION?", 160, 85, 2);
    fireRedText.setTextDatum(TL_DATUM);
    display.fillRoundRect(79, 119, 70, 34, 5, themePrimary());
    display.drawRoundRect(79, 119, 70, 34, 5, themeDark());
    display.fillRoundRect(171, 119, 70, 34, 5, TFT_LIGHTGREY);
    display.drawRoundRect(171, 119, 70, 34, 5, themeDark());
    fireRedText.setTextDatum(MC_DATUM);
    fireRedText.setTextColor(TFT_WHITE, themePrimary());
    fireRedText.drawString("YES", 114, 136, 2);
    fireRedText.setTextColor(themeDark(), TFT_LIGHTGREY);
    fireRedText.drawString("NO", 206, 136, 2);
    fireRedText.setTextDatum(TL_DATUM);
  }
}

void redrawEvolutionInteraction() {
  invalidatePixels(0, 0, 320, 240);
  requestRetainedFrame();
  presentRetainedFrame();
}

bool waitEvolutionCinematic(uint16_t waitMs) {
  uint32_t remaining = waitMs;
  uint32_t previous = millis();
  while (remaining) {
    const uint32_t now = millis();
    const uint32_t elapsed = now - previous;
    previous = now;
    if (!evolutionCancelPromptVisible)
      remaining = elapsed >= remaining ? 0U : remaining - elapsed;

    const TouchPoint point = touch.read();
    if (!point.touched) {
      evolutionTouchLatched = false;
    } else if (!evolutionTouchLatched) {
      evolutionTouchLatched = true;
      if (evolutionCancelPromptVisible) {
        if (inside(point, 79, 119, 70, 34)) {
          evolutionCancelPromptVisible = false;
          evolutionCanceledMessageVisible = true;
          evolutionVisibleSpecies = evolutionFromSpecies;
          evolutionLightSilhouette = false;
          evolutionVisualStage = 0;
          redrawEvolutionInteraction();
          delay(1100);
          evolutionCanceledMessageVisible = false;
          return false;
        }
        if (inside(point, 171, 119, 70, 34)) {
          evolutionCancelPromptVisible = false;
          redrawEvolutionInteraction();
        }
      } else if (evolutionVisualStage < 3 && inside(point, 0, 0, 46, 46)) {
        evolutionCancelPromptVisible = true;
        redrawEvolutionInteraction();
      }
    }
    delay(6);
  }
  return true;
}

bool presentEvolutionCinematic(int16_t x, int16_t y, int16_t width, int16_t height,
                               uint16_t waitMs) {
  invalidatePixels(x, y, width, height);
  requestRetainedFrame();
  presentRetainedFrame();
  return !waitMs || waitEvolutionCinematic(waitMs);
}

bool playEvolutionAnimation(uint16_t fromSpecies, uint16_t toSpecies, bool shiny) {
  // The retained presenter only sends pixels for the active Screen. The old
  // routine painted the RAM canvas while Screen::Battle was still active, so
  // the presenter immediately recomposed the battle and no evolution ever
  // reached the TFT. Give the cinematic a real screen/state of its own.
  evolutionFromSpecies = fromSpecies;
  evolutionToSpecies = toSpecies;
  evolutionVisibleSpecies = fromSpecies;
  evolutionShiny = shiny;
  evolutionLightSilhouette = false;
  evolutionCancelPromptVisible = false;
  evolutionCanceledMessageVisible = false;
  // Ignore the finger that selected a branching evolution until it has been
  // released once; it must never count as a press on the cinematic X.
  evolutionTouchLatched = true;
  evolutionVisualStage = 0;
  battleArenaVisible = false;
  screen = Screen::EvolutionCinematic;
  presentedScreen = Screen::Diagnostic;

  AssetRenderer::clearCache();
  {
    ScopedAssetPreloadBatch preloadBatch;
    AssetRenderer::preload("/pokegochi/assets/firered/evolution_scene/scene.pkg");
    AssetRenderer::preload("/pokegochi/assets/firered/evolution_scene/sparkle.pkg");
    char path[96];
    for (uint8_t tone = 0; tone < 2; ++tone) {
      for (uint8_t form = 0; form < 2; ++form) {
        std::snprintf(path, sizeof(path), "/pokegochi/assets/pokemon/evolution/%s/%03u.pkg",
                      tone ? "light" : "dark", form ? toSpecies : fromSpecies);
        AssetRenderer::preload(path);
      }
    }
    std::snprintf(path, sizeof(path), "/pokegochi/assets/pokemon/%sfront/%03u.pkg",
                  shiny ? "shiny/" : "", toSpecies);
    AssetRenderer::preload(path);
  }

  // FireRed first announces the evolution, then alternates the silhouettes
  // progressively faster before the inward sparkle/flash and reveal.
  if (!presentEvolutionCinematic(0, 0, 320, 240, 1050)) return false;
  evolutionVisualStage = 1;
  static constexpr uint16_t kCadence[] = {240,220,200,180,160,140,120,105,90,78,68,58,50,44};
  for (uint8_t phase = 0; phase < sizeof(kCadence) / sizeof(kCadence[0]); ++phase) {
    evolutionVisibleSpecies = (phase & 1U) ? toSpecies : fromSpecies;
    evolutionLightSilhouette = phase >= 6U && (phase & 2U);
    if (!presentEvolutionCinematic(104, 50, 112, 126, kCadence[phase])) return false;
  }
  evolutionVisibleSpecies = toSpecies;
  evolutionLightSilhouette = true;
  evolutionVisualStage = 2;
  if (!presentEvolutionCinematic(104, 50, 112, 126, 420)) return false;
  evolutionVisualStage = 3;
  presentEvolutionCinematic(0, 58, 320, 178, 1600);
  return true;
}

void drawTradeCinematic() {
  const uint16_t kTradeBlue = themeAccent();
  const uint16_t kTradeDark = themeDark();
  beginScreenPresentation(Screen::TradeCinematic, kTradeBlue);
  display.fillScreen(kTradeBlue);
  for (int16_t y = 0; y < 180; y += 8)
    display.fillRect(0, y, 320, 3, (y / 8) & 1 ? kTradeDark : TFT_CYAN);

  AssetRenderer::draw(display, "/pokegochi/assets/firered/trade/gba.pkg", 18, 18);
  AssetRenderer::draw(display, "/pokegochi/assets/firered/trade/gba.pkg", 238, 18);
  AssetRenderer::draw(display, "/pokegochi/assets/firered/trade/wireless_signal.pkg", 128, 11);
  AssetRenderer::draw(display, "/pokegochi/assets/firered/trade/link_mon_glow.pkg", 144, 70);

  if (tradeVisualStage <= 1U)
    creature(160,tradeVisualY,tradeOutgoingVisual,true);
  else if (tradeVisualStage >= 3U)
    creature(160,tradeVisualY,tradeIncomingVisual,true);
  if (tradeVisualStage == 2U || tradeVisualStage == 3U) {
    char path[80];
    std::snprintf(path, sizeof(path), "/pokegochi/assets/firered/trade/pokeball_%02u.pkg",
                  tradeBallFrame % 12U);
    AssetRenderer::draw(display, path, tradeBallX, tradeVisualY);
  }

  display.fillRect(4, 181, 312, 55, TFT_WHITE);
  display.drawRect(4, 181, 312, 55, TFT_DARKGREY);
  display.drawRect(7, 184, 306, 49, themePrimary());
  const SpeciesData* outgoing = findSpecies(tradeOutgoingVisual.speciesId);
  const SpeciesData* incoming = findSpecies(tradeIncomingVisual.speciesId);
  char line[64];
  if (tradeVisualStage < 3U)
    std::snprintf(line, sizeof(line), "SENDING %s...", outgoing ? outgoing->name : "POKEMON");
  else if (tradeVisualStage < 4U)
    std::snprintf(line, sizeof(line), "%s IS ARRIVING...", incoming ? incoming->name : "POKEMON");
  else
    std::snprintf(line, sizeof(line), "TAKE GOOD CARE OF %s!", incoming ? incoming->name : "POKEMON");
  fireRedText.setTextColor(TFT_DARKGREY, TFT_WHITE);
  fireRedText.drawStringFitted(line, 15, 198, 290, 2);
}

void presentTradeCinematic(uint16_t waitMs) {
  invalidatePixels(0, 0, 320, 240);
  requestRetainedFrame();
  presentRetainedFrame();
  if (waitMs) delay(waitMs);
}

void playTradeAnimation(const OwnedPokemon& outgoing, const OwnedPokemon& incoming) {
  tradeOutgoingVisual = outgoing;
  tradeIncomingVisual = incoming;
  tradeVisualStage = 0; tradeVisualY = 105; tradeBallX = 152; tradeBallFrame = 0;
  screen = Screen::TradeCinematic;
  presentedScreen = Screen::Diagnostic;
  battleArenaVisible = false;

  AssetRenderer::clearCache();
  {
    ScopedAssetPreloadBatch preloadBatch;
    AssetRenderer::preload("/pokegochi/assets/firered/trade/gba.pkg");
    AssetRenderer::preload("/pokegochi/assets/firered/trade/wireless_signal.pkg");
    AssetRenderer::preload("/pokegochi/assets/firered/trade/link_mon_glow.pkg");
    char path[96];
    std::snprintf(path, sizeof(path), "/pokegochi/assets/pokemon/%sfront/%03u.pkg",
                  outgoing.shiny ? "shiny/" : "", outgoing.speciesId);
    AssetRenderer::preload(path);
    std::snprintf(path, sizeof(path), "/pokegochi/assets/pokemon/%sfront/%03u.pkg",
                  incoming.shiny ? "shiny/" : "", incoming.speciesId);
    AssetRenderer::preload(path);
    for (uint8_t frame = 0; frame < 12; ++frame) {
      std::snprintf(path, sizeof(path), "/pokegochi/assets/firered/trade/pokeball_%02u.pkg", frame);
      AssetRenderer::preload(path);
    }
  }

  presentTradeCinematic(700);
  tradeVisualStage = 1;
  for (uint8_t step = 0; step < 8; ++step) {
    tradeVisualY = static_cast<int16_t>(105 - step * 10);
    presentTradeCinematic(75);
  }
  tradeVisualStage = 2; tradeVisualY = 77;
  for (uint8_t step = 0; step < 12; ++step) {
    tradeBallFrame = step;
    tradeBallX = static_cast<int16_t>(76 + step * 14);
    presentTradeCinematic(65);
  }
  tradeVisualStage = 3; tradeBallX = 152;
  for (uint8_t step = 0; step < 8; ++step) {
    tradeBallFrame = static_cast<uint8_t>((11U - step) % 12U);
    tradeVisualY = static_cast<int16_t>(35 + step * 10);
    presentTradeCinematic(75);
  }
  tradeVisualStage = 4; tradeVisualY = 105;
  presentTradeCinematic(1400);

  bagPage = kMultiplayerPage;
  inventoryBattleContext = false;
  inventoryMode = InventoryMode::Browse;
  screen = Screen::Inventory;
  drawInventory();
}

// A card can answer the tiny FAT mount probe at 10 MHz and still drop a long
// sprite read a moment later. Validate the exact files used by the Home and
// battle renderers before declaring the diagnostic ready.
bool verifySdAssetStream() {
  static uint8_t probe[512];
  // PGA1/PGA2 packs are the canonical runtime filesystem. Wireless updates
  // replace this one verified archive rather than rewriting thousands of FAT
  // entries, so a healthy archive must not also depend on stale loose files.
  File packedAssets = SD.open("/pokegochi/pokegochi.pak", FILE_READ);
  if (packedAssets) {
    const bool plausible = packedAssets.size() >= 20U;
    packedAssets.close();
    return plausible;
  }
  static constexpr const char* kCoreAssets[] = {
      "/pokegochi/assets/firered/ui/home_background_base_00.pkg",
      "/pokegochi/assets/firered/ui/home_background_foreground_00.pkg",
      "/pokegochi/assets/pokemon/icons/001_0.pkg",
      "/pokegochi/assets/firered/battle_terrain/grass.pkg"};
  bool healthy = true;
  uint32_t checksum = 2166136261UL;
  for (const char* path : kCoreAssets) {
    File asset = SD.open(path, FILE_READ);
    if (!asset) { healthy = false; break; }
    while (healthy && asset.available()) {
      size_t done = 0;
      uint8_t empty = 0;
      while (done < sizeof(probe) && empty < 4U) {
        const size_t read = asset.read(probe + done, sizeof(probe) - done);
        if (!read) { ++empty; delay(2); continue; }
        done += read;
      }
      // The final block of a package is normally shorter than 512 bytes.
      if (!done) { healthy = false; break; }
      for (size_t index = 0; index < done; ++index) checksum = (checksum ^ probe[index]) * 16777619UL;
    }
    asset.close();
    if (!healthy) break;
  }
  if (!healthy) Serial.println("[SD] core asset read probe failed");
  else Serial.printf("[SD] core asset read OK checksum=%08lX\n", static_cast<unsigned long>(checksum));
  return healthy;
}

uint32_t selectedSdFrequencyHz = 0;

bool verifySdSustainedRead(uint32_t frequency) {
  static uint8_t block[512];
  File archive = SD.open("/pokegochi/pokegochi.pak", FILE_READ);
  // Cards created before PGA1 remain bootable through the per-file probe.
  // A current card is qualified with three 64 KiB passes over the exact
  // contiguous stream used for move batches, not merely a 16-byte FAT open.
  if (!archive) return true;
  constexpr size_t kPassBytes = 64U * 1024U;
  constexpr uint8_t kPasses = 3U;
  const size_t bytesPerPass = std::min<size_t>(kPassBytes, archive.size());
  if (bytesPerPass < 20U) {
    archive.close();
    return false;
  }
  uint32_t checksum = 2166136261UL;
  const uint32_t started = millis();
  bool healthy = true;
  for (uint8_t pass = 0; pass < kPasses && healthy; ++pass) {
    if (!archive.seek(0)) { healthy = false; break; }
    size_t remaining = bytesPerPass;
    while (remaining && healthy) {
      const size_t requested = std::min<size_t>(sizeof(block), remaining);
      size_t done = 0;
      uint8_t emptyReads = 0;
      while (done < requested && emptyReads < 4U) {
        const size_t count = archive.read(block + done, requested - done);
        if (count) { done += count; emptyReads = 0; }
        else { ++emptyReads; yield(); delay(1); }
      }
      if (done != requested) { healthy = false; break; }
      for (size_t index = 0; index < done; ++index)
        checksum = (checksum ^ block[index]) * 16777619UL;
      remaining -= done;
      yield();
    }
  }
  archive.close();
  const uint32_t elapsed = std::max<uint32_t>(1U, millis() - started);
  const uint32_t total = static_cast<uint32_t>(bytesPerPass * kPasses);
  Serial.printf("[SD] sustained @ %lu Hz: %s, %lu bytes, %lu ms, %lu KiB/s, crc=%08lX\n",
                static_cast<unsigned long>(frequency), healthy ? "OK" : "FAIL",
                static_cast<unsigned long>(total), static_cast<unsigned long>(elapsed),
                static_cast<unsigned long>((total * 1000ULL / elapsed) / 1024ULL),
                static_cast<unsigned long>(checksum));
  return healthy;
}

bool testSd(uint8_t maximumAttempts = 8) {
  // The TFT, touch controller and card share the SPI wiring.  Explicitly
  // deselect the other two devices before issuing the card's reset sequence;
  // some CYD batches leave the TFT CS low after a reset.
  constexpr uint8_t kDisplayCsPin = 15;
  pinMode(kDisplayCsPin, OUTPUT);
  digitalWrite(kDisplayCsPin, HIGH);
  pinMode(board::kTouchCsPin, OUTPUT);
  digitalWrite(board::kTouchCsPin, HIGH);
  pinMode(board::kSdCsPin, OUTPUT);
  digitalWrite(board::kSdCsPin, HIGH);
  pinMode(board::kSdMisoPin, INPUT_PULLUP);
  Serial.printf("[SD] MISO idle=%d\n", digitalRead(board::kSdMisoPin));
  // The SD card is an immutable asset pack. Permanent saves live in internal
  // SPIFFS, so this firmware must never create, delete, or modify a file on
  // the removable card. Keeping the VSPI bus alive also avoids repeatedly
  // tearing down the CYD socket after a transient failed mount.
  // Qualify fastest-first. The CYD socket/card combination varies more than
  // the ESP32 controller itself, so a fixed 2 MHz cap punished healthy cards
  // while still failing to protect marginal ones. A production boot tests
  // 10/8/4/2 MHz with a sustained PGA1 read, then retains 1 MHz/400 kHz as
  // recovery fallbacks. A periodic one-shot remount reuses the last proven
  // rate instead of sweeping while the player is waiting at diagnostics.
  constexpr uint32_t kFrequencies[] = {
      10000000UL, 8000000UL, 4000000UL, 2000000UL, 1000000UL, 400000UL};
  const bool oneShot = maximumAttempts == 1U;
  const uint8_t attemptCount = oneShot ? 1U :
      std::max<uint8_t>(1U, std::min<uint8_t>(maximumAttempts,
                                             sizeof(kFrequencies) / sizeof(kFrequencies[0])));
  for (uint8_t attempt = 0; attempt < attemptCount; ++attempt) {
    // Use the faster clock when the socket/card is healthy, but retain the
    // known-good fallback for marginal cards or long jumper traces. Validate
    // only by opening/reading the required asset root; no write test here.
    const uint32_t frequency = oneShot
        ? (selectedSdFrequencyHz ? selectedSdFrequencyHz : 2000000UL)
        : kFrequencies[attempt];
    // Rebuild the filesystem mount only. Do not restart VSPI between retries:
    // the board socket is less reliable after repeated bus teardown.
    SD.end();
    delay(attempt == 0 ? 500 : 220);
    if (attempt == 0) sdSpi.begin(board::kSdSckPin, board::kSdMisoPin, board::kSdMosiPin, board::kSdCsPin);
    digitalWrite(board::kSdCsPin, HIGH);
    // Asset loading is strictly sequential at scene boundaries. Keep a
    // single descriptor available during this mount probe and close every
    // probe file before the renderer starts its own scene transaction.
    const bool mounted = SD.begin(board::kSdCsPin, sdSpi, frequency, "/sd", 1, false);
    const uint8_t cardType = SD.cardType();
    if (!mounted || cardType == CARD_NONE) {
      Serial.printf("[SD] mount retry %u/%u @ %lu Hz (begin=%u type=%u)\n",
                    static_cast<unsigned>(attempt + 1), static_cast<unsigned>(attemptCount),
                    static_cast<unsigned long>(frequency),
                    mounted ? 1U : 0U, static_cast<unsigned>(cardType));
      SD.end();
      continue;
    }
    // During the two-rename commit window a canonical asset (including the
    // manifest or archive) may intentionally be absent while its verified
    // replacement and backup exist. A readable update journal is enough to
    // hand the mounted filesystem to recoverAtBoot(), which completes or
    // rolls back that transaction before AssetRenderer opens the pack.
    bool updateRecoveryPending = false;
    const char* recoveryPaths[] = {
        "/pokegochi/update/state.tmp", "/pokegochi/update/state.bin"};
    for (const char* recoveryPath : recoveryPaths) {
      File recovery = SD.open(recoveryPath, FILE_READ);
      char magic[4]{};
      const bool recognizable = recovery && recovery.size() >= sizeof(magic) &&
          recovery.read(reinterpret_cast<uint8_t*>(magic), sizeof(magic)) == sizeof(magic) &&
          !std::memcmp(magic, "PGUS", sizeof(magic));
      if (recovery) recovery.close();
      if (recognizable) { updateRecoveryPending = true; break; }
    }
    if (updateRecoveryPending) {
      selectedSdFrequencyHz = frequency;
      Serial.printf("[SD] mounted @ %lu Hz for interrupted update recovery\n",
                    static_cast<unsigned long>(frequency));
      return true;
    }
    File manifest = SD.open("/pokegochi/assets/manifest.json", FILE_READ);
    if (!manifest) {
      SD.end();
      delay(220);
      continue;
    }
    uint8_t probe[16]{};
    const size_t read = manifest.read(probe, sizeof(probe));
    manifest.close();
    if (read != sizeof(probe) || !verifySdSustainedRead(frequency) ||
        !verifySdAssetStream()) {
      SD.end();
      delay(220);
      continue;
    }
    selectedSdFrequencyHz = frequency;
    Serial.printf("[SD] SPI %lu Hz\n", static_cast<unsigned long>(frequency));
    return true;
  }
  return false;
}

#ifdef SD_STRESS_TEST
// Temporary hardware-only diagnostic, selected exclusively with the
// SD_STRESS_TEST build flag.  It never writes to the removable card: each
// rate is mounted afresh and repeatedly reads the same large FireRed terrain
// package while reporting a checksum and elapsed time over USB serial.
// Keeping this in the normal firmware source makes the exact production SD
// pins and driver configuration testable without maintaining a second sketch.
void runSdStressSuite() {
  constexpr uint32_t kRates[] = {
      400000UL, 1000000UL, 2000000UL, 4000000UL, 8000000UL,
      10000000UL, 16000000UL, 20000000UL, 25000000UL};
  constexpr const char* kProbePath = "/pokegochi/assets/firered/battle_terrain/grass.pkg";
  constexpr uint8_t kPasses = 6;
  constexpr const char* kSceneFiles[] = {
      "/pokegochi/assets/firered/ui/home_background_base_00.pkg",
      "/pokegochi/assets/firered/ui/home_background_foreground_00.pkg",
      "/pokegochi/assets/firered/battle_terrain/grass.pkg",
      "/pokegochi/assets/pokemon/front/001.pkg",
      "/pokegochi/assets/pokemon/back/001.pkg",
      "/pokegochi/assets/pokemon/icons/001_0.pkg"};
  static uint8_t buffer[4096];

  pinMode(15, OUTPUT); digitalWrite(15, HIGH);  // TFT CS
  pinMode(board::kTouchCsPin, OUTPUT); digitalWrite(board::kTouchCsPin, HIGH);
  pinMode(board::kSdCsPin, OUTPUT); digitalWrite(board::kSdCsPin, HIGH);
  pinMode(board::kSdMisoPin, INPUT_PULLUP);
  sdSpi.begin(board::kSdSckPin, board::kSdMisoPin, board::kSdMosiPin, board::kSdCsPin);
  Serial.println("[SDTEST] BEGIN read-only frequency sweep");

#ifndef SD_TFT_INTERLEAVE_ONLY
  for (uint32_t rate : kRates) {
    SD.end();
    delay(180);
    digitalWrite(board::kSdCsPin, HIGH);
    const uint32_t mountStarted = millis();
    const bool mounted = SD.begin(board::kSdCsPin, sdSpi, rate, "/sd", 1, false) &&
                         SD.cardType() != CARD_NONE;
    const uint32_t mountMs = millis() - mountStarted;
    if (!mounted) {
      Serial.printf("[SDTEST] rate=%lu mount=FAIL mountMs=%lu miso=%d\n",
                    static_cast<unsigned long>(rate), static_cast<unsigned long>(mountMs),
                    digitalRead(board::kSdMisoPin));
      continue;
    }

    uint32_t totalBytes = 0;
    uint32_t checksum = 2166136261UL;
    bool good = true;
    const uint32_t readStarted = millis();
    for (uint8_t pass = 0; pass < kPasses && good; ++pass) {
      File file = SD.open(kProbePath, FILE_READ);
      if (!file) { good = false; break; }
      while (file.available()) {
        const size_t want = std::min<size_t>(sizeof(buffer), static_cast<size_t>(file.available()));
        const size_t count = file.read(buffer, want);
        if (!count) { good = false; break; }
        totalBytes += static_cast<uint32_t>(count);
        for (size_t index = 0; index < count; ++index) checksum = (checksum ^ buffer[index]) * 16777619UL;
        yield();
      }
      file.close();
    }
    const uint32_t readMs = millis() - readStarted;
    const uint32_t kibPerSecond = readMs ? (totalBytes * 1000UL / 1024UL / readMs) : 0;
    Serial.printf("[SDTEST] rate=%lu mount=OK mountMs=%lu read=%s bytes=%lu readMs=%lu KiBps=%lu hash=%08lX\n",
                  static_cast<unsigned long>(rate), static_cast<unsigned long>(mountMs),
                  good ? "OK" : "FAIL", static_cast<unsigned long>(totalBytes),
                  static_cast<unsigned long>(readMs), static_cast<unsigned long>(kibPerSecond),
                  static_cast<unsigned long>(checksum));
  }

  // Scene changes in Pokegochi do not only stream one terrain; they open a
  // mixture of backgrounds, sprites and icons. Repeat that exact pattern to
  // expose FAT/open failures that a single contiguous file could hide.
  constexpr uint32_t kSustainedRates[] = {4000000UL, 10000000UL, 20000000UL};
  constexpr uint8_t kSceneLoops = 36;
  for (uint32_t rate : kSustainedRates) {
    SD.end(); delay(180); digitalWrite(board::kSdCsPin, HIGH);
    const bool mounted = SD.begin(board::kSdCsPin, sdSpi, rate, "/sd", 1, false) &&
                         SD.cardType() != CARD_NONE;
    if (!mounted) {
      Serial.printf("[SDTEST] sustained rate=%lu mount=FAIL\n", static_cast<unsigned long>(rate));
      continue;
    }
    bool good = true;
    uint32_t totalBytes = 0, checksum = 2166136261UL;
    const uint32_t started = millis();
    for (uint8_t loop = 0; loop < kSceneLoops && good; ++loop) {
      for (const char* path : kSceneFiles) {
        File file = SD.open(path, FILE_READ);
        if (!file) { good = false; break; }
        while (file.available()) {
          const size_t want = std::min<size_t>(sizeof(buffer), static_cast<size_t>(file.available()));
          const size_t count = file.read(buffer, want);
          if (!count) { good = false; break; }
          totalBytes += static_cast<uint32_t>(count);
          for (size_t index = 0; index < count; ++index) checksum = (checksum ^ buffer[index]) * 16777619UL;
          yield();
        }
        file.close();
        if (!good) break;
      }
    }
    const uint32_t elapsed = millis() - started;
    const uint32_t kibPerSecond = elapsed ? (totalBytes * 1000UL / 1024UL / elapsed) : 0;
    Serial.printf("[SDTEST] sustained rate=%lu reads=%u/%u result=%s bytes=%lu ms=%lu KiBps=%lu hash=%08lX\n",
                  static_cast<unsigned long>(rate), static_cast<unsigned>(kSceneLoops * 6U),
                  static_cast<unsigned>(kSceneLoops * 6U), good ? "OK" : "FAIL",
                  static_cast<unsigned long>(totalBytes), static_cast<unsigned long>(elapsed),
                  static_cast<unsigned long>(kibPerSecond), static_cast<unsigned long>(checksum));
  }
#endif

  // The game starts failing only after its TFT has rendered the Home chrome.
  // Reproduce that electrical/driver load here while the SD is read directly,
  // so a successful card-only sweep cannot mask an interaction between the
  // two independent SPI hosts.
  // Use the production retry ladder. A cold CYD socket occasionally misses
  // the first card-identification command, so a one-attempt benchmark would
  // measure insertion timing instead of TFT/SD coexistence.
  // Also remove the display backlight load for the identification phase. If
  // this is the difference between a failed and a successful mount, the
  // board's 3.3-V rail—not the card format or asset renderer—is the culprit.
  backlight.setEnabled(false);
  delay(180);
  const bool displayMounted = testSd();
  backlight.setEnabled(true);
  bool displayGood = displayMounted;
  uint32_t displayBytes = 0, displayChecksum = 2166136261UL;
  const uint32_t displayStarted = millis();
  for (uint16_t iteration = 0; iteration < 48U && displayGood; ++iteration) {
    // Comparable to a complete menu repaint: a full screen plus the framed
    // playfield and several coloured controls.
    display.fillScreen((iteration & 1U) ? themePrimary() : TFT_DARKGREEN);
    display.fillRoundRect(4, 4, 312, 232, 7, TFT_ORANGE);
    display.fillRect(8, 49, 304, 134, (iteration & 2U) ? themePale() : TFT_GREEN);
    display.fillRoundRect(9, 190, 57, 40, 4, TFT_WHITE);
    display.fillRoundRect(71, 190, 57, 40, 4, TFT_WHITE);
    for (const char* path : kSceneFiles) {
      File file = SD.open(path, FILE_READ);
      if (!file) { displayGood = false; break; }
      while (file.available()) {
        const size_t want = std::min<size_t>(sizeof(buffer), static_cast<size_t>(file.available()));
        const size_t count = file.read(buffer, want);
        if (!count) { displayGood = false; break; }
        displayBytes += static_cast<uint32_t>(count);
        for (size_t index = 0; index < count; ++index) displayChecksum = (displayChecksum ^ buffer[index]) * 16777619UL;
      }
      file.close();
      if (!displayGood) break;
    }
    yield();
  }
  const uint32_t displayElapsed = millis() - displayStarted;
  Serial.printf("[SDTEST] tft-interleave mount=%s result=%s opens=%u bytes=%lu ms=%lu hash=%08lX\n",
                displayMounted ? "OK" : "FAIL", displayGood ? "OK" : "FAIL", 48U * 6U,
                static_cast<unsigned long>(displayBytes), static_cast<unsigned long>(displayElapsed),
                static_cast<unsigned long>(displayChecksum));
  SD.end();
  Serial.println("[SDTEST] END -- reset board to run again");
}
#endif

struct AssetPackageHeader {
  char magic[4];
  uint16_t width;
  uint16_t height;
  uint16_t transparent;
} __attribute__((packed));

bool readAssetFully(File& file, uint8_t* buffer, size_t length) {
  size_t offset = 0;
  uint8_t emptyReads = 0;
  while (offset < length && emptyReads < 4U) {
    const size_t read = file.read(buffer + offset, length - offset);
    if (!read) {
      ++emptyReads;
      delay(1);
      continue;
    }
    offset += read;
    emptyReads = 0;
  }
  return offset == length;
}

bool testAssetFile(const char* path, uint16_t expectedWidth, uint16_t expectedHeight) {
  File file = SD.open(path, FILE_READ);
  AssetPackageHeader header{};
  if (!file) {
    Serial.printf("[ASSET] %s: OPEN FAIL\n", path);
    return false;
  }
  const size_t actualSize = file.size();
  const bool headerRead = readAssetFully(file, reinterpret_cast<uint8_t*>(&header), sizeof(header));
  uint8_t bitsPerPixel = 16;
  uint8_t paletteCount = 0;
  if (headerRead && std::memcmp(header.magic, "PKG2", 4) == 0) {
    uint8_t tail[2]{};
    if (!readAssetFully(file, tail, sizeof(tail))) {
      file.close();
      Serial.printf("[ASSET] %s: PKG2 TAIL FAIL\n", path);
      return false;
    }
    bitsPerPixel = tail[0];
    paletteCount = tail[1];
  }
  const size_t pixels = static_cast<size_t>(expectedWidth) * expectedHeight;
  const size_t payload = bitsPerPixel == 4U ? (pixels + 1U) / 2U
                       : bitsPerPixel == 6U ? (pixels * 6U + 7U) / 8U
                       : bitsPerPixel == 8U ? pixels : pixels * sizeof(uint16_t);
  const bool pkg1 = headerRead && std::memcmp(header.magic, "PKG1", 4) == 0;
  const bool pkg2 = headerRead && std::memcmp(header.magic, "PKG2", 4) == 0 &&
                    (bitsPerPixel == 4U || bitsPerPixel == 6U || bitsPerPixel == 8U) && paletteCount &&
                    (bitsPerPixel != 4U || paletteCount <= 16U);
  const bool headerValid = (pkg1 || pkg2) && header.width == expectedWidth && header.height == expectedHeight;
  const size_t headerBytes = sizeof(header) + (pkg2 ? 2U + static_cast<size_t>(paletteCount) * sizeof(uint16_t) : 0U);
  const bool sizeValid = actualSize == headerBytes + payload;
  bool ok = headerValid && sizeValid;
  // verifySdAssetStream() performs the full sequential stream check for the
  // core scene.  The diagnostic only needs to prove the package metadata is
  // coherent; rereading ten complete terrain files here delayed every boot.
  const size_t finalPosition = file.position();
  if (file) file.close();
  Serial.printf("[ASSET] %s: %s open=1 size=%u/%u hdr=%u dims=%ux%u pos=%u\n", path,
                ok ? "OK" : "FAIL", static_cast<unsigned>(actualSize),
                static_cast<unsigned>(headerBytes + payload), headerRead ? 1U : 0U,
                static_cast<unsigned>(header.width), static_cast<unsigned>(header.height),
                static_cast<unsigned>(finalPosition));
  return ok;
}

void logSdDirectory(const char* path) {
  File directory = SD.open(path);
  if (!directory) {
    Serial.printf("[SDDIR] %s: OPEN FAIL\n", path);
    return;
  }
  if (!directory.isDirectory()) {
    Serial.printf("[SDDIR] %s: NOT A DIRECTORY\n", path);
    directory.close();
    return;
  }
  Serial.printf("[SDDIR] %s:\n", path);
  uint8_t listed = 0;
  for (File entry = directory.openNextFile(); entry && listed < 12U; entry = directory.openNextFile(), ++listed) {
    Serial.printf("  %s %s %u\n", entry.isDirectory() ? "DIR " : "FILE", entry.name(),
                  static_cast<unsigned>(entry.size()));
    entry.close();
  }
  if (!listed) Serial.println("  (empty)");
  directory.close();
}

bool testSdAssets() {
  assetPackUpdateRequired = false;
  // Do this before walking or probing the asset tree. Core files alone are
  // insufficient: an older pack can boot Home successfully while lacking
  // the per-frame sprites used by newer battle animations.
  File version = SD.open("/pokegochi/assets/pack_version.txt", FILE_READ);
  if (!version) {
    Serial.println("[ASSET] pack version missing; update the microSD");
    assetPackUpdateRequired = true;
    return false;
  }
  char versionText[8]{};
  const size_t versionBytes = version.readBytes(versionText, sizeof(versionText) - 1U);
  version.close();
  const uint16_t foundVersion = versionBytes ? static_cast<uint16_t>(std::strtoul(versionText, nullptr, 10)) : 0U;
  if (foundVersion != kRequiredAssetPackVersion) {
    Serial.printf("[ASSET] pack version %u, firmware requires %u\n",
                  static_cast<unsigned>(foundVersion),
                  static_cast<unsigned>(kRequiredAssetPackVersion));
    assetPackUpdateRequired = true;
    return false;
  }
  File animationCatalog = SD.open("/pokegochi/assets/animation_catalog.txt", FILE_READ);
  if (!animationCatalog) {
    Serial.println("[ASSET] animation catalog missing; update the microSD");
    assetPackUpdateRequired = true;
    return false;
  }
  char catalogText[24]{};
  const size_t catalogBytes = animationCatalog.readBytes(
      catalogText, sizeof(catalogText) - 1U);
  animationCatalog.close();
  while (catalogBytes && (catalogText[std::strlen(catalogText) - 1U] == '\r' ||
                          catalogText[std::strlen(catalogText) - 1U] == '\n'))
    catalogText[std::strlen(catalogText) - 1U] = '\0';
  if (!catalogBytes || std::strcmp(catalogText, battleAnimationCatalogId()) != 0) {
    Serial.printf("[ASSET] animation catalog %.16s, firmware requires %.16s\n",
                  catalogBytes ? catalogText : "missing", battleAnimationCatalogId());
    assetPackUpdateRequired = true;
    return false;
  }
  if (AssetRenderer::usingArchive()) {
    static constexpr const char* kArchiveProbes[] = {
        "/pokegochi/assets/pokemon/icons/001_0.pkg",
        "/pokegochi/assets/pokemon/front/001.pkg",
        "/pokegochi/assets/firered/ui/home_background_base_00.pkg",
        "/pokegochi/assets/firered/battle_terrain/grass.pkg"};
    bool okay = AssetRenderer::beginPreloadBatch();
    for (const char* path : kArchiveProbes) okay = AssetRenderer::preload(path) && okay;
    AssetRenderer::endPreloadBatch();
    const bool readFailed = AssetRenderer::takeIoFailure();
    AssetRenderer::clearCache();
    Serial.printf("[ASSET] archive probe %s\n", okay && !readFailed ? "OK" : "FAIL");
    return okay && !readFailed;
  }
  // The current version marker describes the indexed pack. Accepting the
  // legacy loose-file fallback here could validate old graphics under a new
  // marker after a damaged OTA commit, defeating automatic rollback.
  Serial.println("[ASSET] current asset pack archive is unavailable");
  assetPackUpdateRequired = true;
  return false;
}

