void prepareProfessorScene(const char* scenePath, const uint16_t* speciesIds = nullptr) {
  bool ready = AssetRenderer::isPreloaded(scenePath);
  char pokemonPath[80];
  if (speciesIds) {
    for (uint8_t index = 0; index < 3; ++index) {
      std::snprintf(pokemonPath, sizeof(pokemonPath),
                    "/pokegochi/assets/pokemon/front/%03u.pkg", speciesIds[index]);
      ready = AssetRenderer::isPreloaded(pokemonPath) && ready;
    }
  }
  if (ready) return;
  AssetRenderer::clearCache();
  AssetRenderer::preload(scenePath);
  if (speciesIds) {
    for (uint8_t index = 0; index < 3; ++index) {
      std::snprintf(pokemonPath, sizeof(pokemonPath),
                    "/pokegochi/assets/pokemon/front/%03u.pkg", speciesIds[index]);
      AssetRenderer::preload(pokemonPath);
    }
  }
}

