bool presentPokedexCompletionRewardIfNeeded() {
  const PokedexRewardUpdate update = PokedexRewards::reconcile(
      gameSave.pokedex, gameSave.inventory, gameSave.gymProgress.unlockedGeneration, gameSave.flags);
  if (update.grantedGenerations != 0) {
    saveDirty = true;
    saveNow();
  }
  if (update.pendingGeneration == 0) return false;
  presentedDexRewardGeneration = update.pendingGeneration;
  screen = Screen::PokedexCompleteReward;
  drawPokedexCompleteReward();
  return true;
}

