void homeMoveButton() {
  const int16_t x = kHomeBottomX[0], y = kHomeBottomY;
  homeFrame(x, y, kHomeButtonWidth, kHomeButtonHeight);
  const int16_t cx = x + kHomeButtonWidth / 2;
  const int16_t cy = y + kHomeButtonHeight / 2;
  const uint16_t outline = TFT_DARKGREY;
  const uint16_t fill = homeMoveMode ? TFT_ORANGE : themePrimary();
  // A compact four-way movement glyph remains readable without consuming an
  // SD asset and therefore works even while the card is being remounted.
  display.fillRect(cx - 2, cy - 9, 5, 19, outline);
  display.fillRect(cx - 9, cy - 2, 19, 5, outline);
  display.fillTriangle(cx, cy - 12, cx - 5, cy - 6, cx + 5, cy - 6, outline);
  display.fillTriangle(cx, cy + 12, cx - 5, cy + 6, cx + 5, cy + 6, outline);
  display.fillTriangle(cx - 12, cy, cx - 6, cy - 5, cx - 6, cy + 5, outline);
  display.fillTriangle(cx + 12, cy, cx + 6, cy - 5, cx + 6, cy + 5, outline);
  display.fillRect(cx - 1, cy - 8, 3, 17, fill);
  display.fillRect(cx - 8, cy - 1, 17, 3, fill);
  display.fillCircle(cx, cy, 3, fill);
  if (homeMoveMode) display.drawRect(x + 5, y + 5, kHomeButtonWidth - 10,
                                     kHomeButtonHeight - 10, TFT_ORANGE);
}

void homePokecenterButton(int16_t x, int16_t y) {
  // Keep the Pokécenter consistent with the compact square controls rather
  // than reserving a wide banner in the Home header.
  homeFrame(x, y, kHomeButtonWidth, kHomeButtonHeight);
  // Nurse Joy's front-facing FireRed portrait remains recognisable at 24px
  // and leaves the top-right corner clear for the Center charge badge.
  const bool iconDrawn = sdReady && AssetRenderer::draw(display,
      "/pokegochi/assets/firered/ui/home_pokecenter.pkg",
      x + (kHomeButtonWidth - kHomeIconSize) / 2,
      y + (kHomeButtonHeight - kHomeIconSize) / 2);
  // SD retry fallback remains a conventional Pokeball so Center is still
  // identifiable while the asset pack is being remounted.
  if (!iconDrawn) {
    const int16_t centerX = x + kHomeButtonWidth / 2;
    const int16_t centerY = y + kHomeButtonHeight / 2;
    display.fillCircle(centerX, centerY, 10, TFT_DARKGREY);
    display.fillCircle(centerX, centerY, 8, TFT_RED);
    display.fillRect(centerX - 8, centerY, 17, 8, TFT_WHITE);
    display.fillRect(centerX - 9, centerY - 1, 19, 3, TFT_DARKGREY);
    display.fillCircle(centerX, centerY, 4, TFT_DARKGREY);
    display.fillCircle(centerX, centerY, 2, TFT_WHITE);
  }
  char charges[4];
  std::snprintf(charges, sizeof(charges), "%u", gameSave.wildEncounterClock.available);
  const int16_t badgeX = x + kHomeButtonWidth - 5;
  const int16_t badgeY = y + 7;
  display.fillCircle(badgeX, badgeY, 7, TFT_RED);
  display.drawCircle(badgeX, badgeY, 7, TFT_WHITE);
  fireRedText.setTextColor(TFT_WHITE, TFT_RED); fireRedText.setTextDatum(MC_DATUM);
  // FireRed's digit ink occupies rows 2..11 of its 16px line box. Its
  // mathematical centre therefore looks two pixels too high inside a badge;
  // centre the visible ink, not the otherwise transparent line box.
  fireRedText.drawString(charges, badgeX, badgeY + 2, 1); fireRedText.setTextDatum(TL_DATUM);
}

