  constexpr int16_t iconX = x + (kHomeButtonWidth - kHomeIconSize) / 2;
  constexpr int16_t iconY = y + (kHomeButtonHeight - kHomeIconSize) / 2;
  constexpr uint16_t outline = TFT_DARKGREY, steel = 0xD71A, shadow = 0x7BCF;
