uint8_t martRotationProgressSlices() {
  constexpr uint8_t kSlices = 12;
  const uint32_t elapsed = std::min(gameSave.mart.elapsedSeconds, Economy::kRotationSeconds);
  return static_cast<uint8_t>(std::min<uint32_t>(
      kSlices, (elapsed * kSlices) / Economy::kRotationSeconds));
}

void drawMartRotationProgress() {
  constexpr int16_t cx = 306, cy = 220;
  // Twelve points around a six-pixel radius form a tiny clock face. Filling
  // consecutive center triangles creates a clockwise radial sweep rather
  // than the previous vertical liquid gauge.
  constexpr int8_t clockX[13] = {0, 3, 5, 6, 5, 3, 0, -3, -5, -6, -5, -3, 0};
  constexpr int8_t clockY[13] = {-6, -5, -3, 0, 3, 5, 6, 5, 3, 0, -3, -5, -6};
  constexpr uint16_t outline = TFT_DARKGREEN;
  constexpr uint16_t fill = 0x2D7F;
  display.fillCircle(cx, cy, 7, outline);
  display.fillCircle(cx, cy, 6, TFT_WHITE);
  const uint8_t slices = martRotationProgressSlices();
  for (uint8_t slice = 0; slice < slices; ++slice)
    display.fillTriangle(cx, cy, cx + clockX[slice], cy + clockY[slice],
                         cx + clockX[slice + 1U], cy + clockY[slice + 1U], fill);
  display.drawCircle(cx, cy, 7, outline);
}

