  char charges[4]; std::snprintf(charges, sizeof(charges), "%u", available);
  const int16_t badgeX = x + kHomeButtonWidth - 5;
  const int16_t badgeY = kHomeTopY + 7;
  display.fillCircle(badgeX, badgeY, 7, badgeColor);
  display.drawCircle(badgeX, badgeY, 7, TFT_WHITE);
  fireRedText.setTextColor(TFT_WHITE, badgeColor); fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawString(charges, badgeX, badgeY + 2, 1);
