void drawWirelessUpdateBody() {
  drawGbaInsetPanel(13, 48, 294, 54, 7, kBattleFrameShadow,
                    kSettingsWell, kBattleFrameGold);
  fireRedText.setTextColor(kBattleInk, kSettingsWell);
  fireRedText.drawString(wirelessUpdate.connected() ? "PHONE CONNECTED" : "READY FOR PHONE", 23, 57, 2);
  fireRedText.setTextColor(TFT_DARKGREY, kSettingsWell);
  fireRedText.drawStringFitted("PAIRING CODE", 23, 82, 120, 1);
  char pairing[16];
  std::snprintf(pairing, sizeof(pairing), "%06lu",
                static_cast<unsigned long>(wirelessUpdate.pairingCode()));
  display.fillRoundRect(169, 57, 124, 36, 7, themePale());
  display.drawRoundRect(169, 57, 124, 36, 7, themeDark());
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.setTextColor(themeDark(), themePale());
  // The pairing code is the one value the player must read while also
  // looking at the phone. Use the full double-scale FireRed numerals instead
  // of the legacy 8 px artwork font; six digits still fit comfortably in the
  // 124 x 36 code well.
  fireRedText.drawString(pairing, 231, 75, 4);
  fireRedText.setTextDatum(TL_DATUM);

  drawGbaInsetPanel(13, 108, 294, 79, 7, kBattleFrameShadow,
                    kSettingsWell, kBattleFrameGold);
  const uint8_t progress = wirelessUpdate.progressPercent();
  char progressText[16];
  std::snprintf(progressText, sizeof(progressText), "%u%%", static_cast<unsigned>(progress));
  fireRedText.setTextColor(kBattleInk, kSettingsWell);
  fireRedText.drawString("UPDATE PROGRESS", 23, 117, 2);
  fireRedText.setTextDatum(TR_DATUM);
  fireRedText.setTextColor(themeDark(), kSettingsWell);
  fireRedText.drawString(progressText, 293, 120, 2);
  fireRedText.setTextDatum(TL_DATUM);
  display.fillRoundRect(23, 140, 270, 17, 5, kBattleFrameShadow);
  display.fillRoundRect(26, 143, 264, 11, 3, TFT_WHITE);
  const int16_t filled = static_cast<int16_t>(264U * progress / 100U);
  if (filled > 0) display.fillRoundRect(26, 143, filled, 11, 3, themeAccent());
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.setTextColor(kBattleInk, kSettingsWell);
  fireRedText.drawStringFitted(wirelessUpdate.statusText(), 160, 173, 272, 1);
  fireRedText.setTextDatum(TL_DATUM);

  drawGbaInsetPanel(11, 194, 298, 38, 6, kBattleFrameShadow,
                    kSettingsWell, kBattleFrameGold);
  if (wirelessUpdate.busy()) {
    button(86, 199, 148, 29, "UPDATING...", kSettingsLine);
  } else {
    button(86, 199, 148, 29,
           wirelessUpdate.error() == WirelessUpdate::ErrorCode::None ? "BACK" : "CLOSE",
           TFT_RED);
  }
}

void drawWirelessUpdate() {
  beginScreenPresentation(Screen::WirelessUpdate, TFT_BLACK);
  drawSettingsShell("WIRELESS UPDATE");
  drawWirelessUpdateBody();
}

void refreshWirelessUpdate() {
  // BLE acknowledges every storage block. Repainting the 320x240 frame for
  // every ACK would throttle the transfer; only the live cards are dirty.
  invalidatePixels(11, 48, 298, 184);
  drawWirelessUpdateBody();
}

void openWirelessUpdate() {
  wirelessUpdateFromDiagnostic = screen == Screen::Diagnostic;
  if (saveDirty) saveNow();
  multiplayer.shutdown();
  AssetRenderer::releaseSceneWorkspaceForRadio();
  preparedUiSceneKey = 0;
  preparedUiSceneComplete = false;
  wirelessUpdate.begin(multiplayer.playerId(), kGameVersion,
                       kRequiredAssetPackVersion, sdReady);
  screen = Screen::WirelessUpdate;
  requestRetainedFrame();
  drawWirelessUpdate();
}

void closeWirelessUpdate() {
  wirelessUpdate.shutdown(false);
  AssetRenderer::restoreSceneWorkspace(false);
  preparedUiSceneKey = 0;
  preparedUiSceneComplete = false;
  if (wirelessUpdateFromDiagnostic) {
    wirelessUpdateFromDiagnostic = false;
    screen = Screen::Diagnostic;
    requestRetainedFrame();
    drawDiagnostic();
  } else {
    settingsPage = 0;
    settingsScroll = 3;
    screen = Screen::Settings;
    requestRetainedFrame();
    drawSettings();
  }
}

// Settings remains open while these values change. Repaint a complete card,
// not the screen: the retained presenter then transmits only the changed
// pixels and the layered chrome never leaves stale edges behind.
void refreshSettingsBrightness() {
  invalidatePixels(13, 47, 294, 66);
  drawSettingsBrightnessCard();
}

void refreshSettingsTimeout() {
  invalidatePixels(13, 117, 294, 80);
  drawSettingsTimeoutCard();
}

void refreshSettingsBattleText() {
  invalidatePixels(13, 161, 294, 37);
  drawSettingsBattleTextCard();
}

void refreshSettingsBackgroundPreview() {
  invalidatePixels(6, 42, 308, 156);
  drawSettingsBackgroundPreview();
}

void scheduleSettingsBackgroundPrefetch(int8_t direction) {
  if (!direction) { settingsBackgroundPrefetch = 0xFF; return; }
  const int16_t count = HomeBackgrounds::kCount;
  const int16_t selected = gameSave.settings.homeBackground;
  settingsBackgroundPrefetch = static_cast<uint8_t>(
      (selected + (direction > 0 ? 1 : count - 1)) % count);
}

void serviceSettingsBackgroundPrefetch() {
  if (settingsBackgroundPrefetch == 0xFF || displaySleeping ||
      screen != Screen::Settings || settingsPage != 1 || retainedFrameRequested) return;
  const uint8_t background = settingsBackgroundPrefetch;
  settingsBackgroundPrefetch = 0xFF;
  char path[80];
  std::snprintf(path, sizeof(path),
                "/pokegochi/assets/firered/ui/home_background_%02u.pkg", background);
  const uint32_t started = millis();
  const bool ready = sdReady && AssetRenderer::preload(path);
  if (AssetRenderer::takeIoFailure()) storageRecoveryPending = true;
  Serial.printf("[GFX] background preview prefetch %u %s %lums\n",
                static_cast<unsigned>(background), ready ? "OK" : "FAIL",
                static_cast<unsigned long>(millis() - started));
}

uint32_t eggIncubationSeconds(const EggState& egg) {
  return egg.rarity == EggRarity::Common ? EggSystem::kCommonSeconds :
      egg.rarity == EggRarity::Uncommon ? EggSystem::kUncommonSeconds :
      EggSystem::kRareSeconds;
}

const char* eggOriginName(const EggState& egg) {
  if (egg.rarity == EggRarity::Special) return "BATTLE TOWER";
  switch (egg.region) {
    case 2: return "JOHTO";
    case 3: return "HOENN";
    default: return "KANTO";
  }
}

void formatEggTimeLeft(const EggState& egg, char* output, size_t outputSize) {
  if (!output || !outputSize) return;
  if (EggSystem::ready(egg)) {
    std::snprintf(output, outputSize, "READY");
    return;
  }
  const uint32_t days = egg.remainingSeconds / 86400U;
  const uint32_t hours = (egg.remainingSeconds % 86400U) / 3600U;
  const uint32_t minutes = (egg.remainingSeconds % 3600U + 59U) / 60U;
  if (days)
    std::snprintf(output, outputSize, "%luD %02luH",
                  static_cast<unsigned long>(days), static_cast<unsigned long>(hours));
  else if (hours)
    std::snprintf(output, outputSize, "%luH %02luM",
                  static_cast<unsigned long>(hours), static_cast<unsigned long>(minutes));
  else
    std::snprintf(output, outputSize, "%lu MIN",
                  static_cast<unsigned long>(std::max<uint32_t>(1U, minutes)));
}

