uint32_t nextPokecenterSceneRandom() {
  if (!pokecenterSceneRandomState) {
    pokecenterSceneRandomState = 0x50434E54UL ^ gameSave.playTimeSeconds ^
        (gameSave.bootCount * 0x9E3779B9UL) ^ gameSave.collection.nextUid ^ millis();
    if (!pokecenterSceneRandomState) pokecenterSceneRandomState = 1U;
  }
  // Xorshift32 is sufficient for a visual choice and does not consume the
  // deterministic battle RNG used by accuracy, damage and encounters.
  pokecenterSceneRandomState ^= pokecenterSceneRandomState << 13U;
  pokecenterSceneRandomState ^= pokecenterSceneRandomState >> 17U;
  pokecenterSceneRandomState ^= pokecenterSceneRandomState << 5U;
  return pokecenterSceneRandomState;
}

void ensurePokecenterSceneSelected() {
  if (pokecenterSceneIndex < kPokecenterSceneCount) return;
  pokecenterSceneIndex = static_cast<uint8_t>(
      nextPokecenterSceneRandom() % kPokecenterSceneCount);
}

void advancePokecenterScene() {
  ensurePokecenterSceneSelected();
  // Pick among the other nine scenes rather than rerolling all ten. Thus a
  // successful heal always changes the room shown on the following visit.
  const uint8_t offset = static_cast<uint8_t>(
      1U + nextPokecenterSceneRandom() % (kPokecenterSceneCount - 1U));
  pokecenterSceneIndex = static_cast<uint8_t>(
      (pokecenterSceneIndex + offset) % kPokecenterSceneCount);
}

void drawPokecenterConfirm() {
  ensurePokecenterSceneSelected();
  char scene[72];
  std::snprintf(scene, sizeof(scene),
                "/pokegochi/assets/pokecenter/scene_%02u.pkg",
                static_cast<unsigned>(pokecenterSceneIndex));
  const char* assets[] = {scene};
  prepareUiScene(0x50430000UL | pokecenterSceneIndex, assets, 1);
  beginScreenPresentation(Screen::PokecenterConfirm, TFT_BLACK);

  // The upper two thirds are an exact FireRed Pokemon Center map viewport,
  // including Nurse Joy behind the counter and the original healing machine.
  // Keep the fallback opaque so a damaged/old card can never expose fragments
  // of the previous Home screen while storage recovery is being scheduled.
  if (!sdReady || !AssetRenderer::draw(display, scene, 0, 0)) {
    display.fillRect(0, 0, 320, 160, themePale());
    display.fillRect(38, 23, 244, 78, TFT_WHITE);
    display.fillRect(38, 82, 244, 19, TFT_RED);
    display.fillRect(145, 42, 30, 40, TFT_DARKGREY);
    display.fillCircle(160, 44, 10, 0xFD75);
    display.fillRect(151, 55, 18, 20, 0xFD75);
  }

  // FireRed presents dialogue on the left and its YES/NO command window on
  // the right.  There are no floating modern buttons over the map scene.
  drawFireRedBattleWindow(0, 160, 222, 80, kBattleFrameGold, themePrimary());
  char charges[96];
  const uint8_t available = gameSave.wildEncounterClock.available;
  std::snprintf(charges, sizeof(charges),
                "WELCOME!\nRESTORE YOUR PARTY?\nCHARGES LEFT: %u",
                available);
  fireRedText.setTextColor(TFT_WHITE, themePrimary());
  fireRedText.setTextDatum(TL_DATUM);
  fireRedText.drawTextBox(charges, 10, 167, 202, 66, 0);

  drawFireRedBattleWindow(220, 160, 100, 80, kBattleCommandFrame, kBattlePaper);
  display.drawFastHLine(225, 200, 90, kBattleFrameGold);
  fireRedText.setTextColor(kBattleInk, kBattlePaper);
  fireRedText.setTextDatum(MC_DATUM);
  display.fillTriangle(228, 180, 236, 175, 236, 185, TFT_RED);
  fireRedText.drawString("YES", 270, 181, 1);
  fireRedText.drawString("NO", 270, 219, 1);
  fireRedText.setTextDatum(TL_DATUM);
}

void drawEggHatch() {
  beginScreenPresentation(Screen::EggHatch, TFT_BLACK);
  drawEggShell("EGG HATCH");
  drawGbaInsetPanel(54, 47, 212, 109, 8, kBattleFrameShadow,
                    themePale(), kBattleFrameGold);
  // Symmetrical rays and sparkles frame the original 64x64 hatch assets.
  // They are deterministic, so repeated animation frames never shimmer due
  // to unrelated background pixels changing.
  display.drawFastHLine(69, 101, 24, TFT_WHITE);
  display.drawFastHLine(227, 101, 24, TFT_WHITE);
  display.drawFastVLine(160, 56, 14, TFT_WHITE);
  display.drawFastVLine(160, 137, 12, TFT_WHITE);
  display.drawLine(81, 68, 99, 82, TFT_YELLOW);
  display.drawLine(239, 68, 221, 82, TFT_YELLOW);
  display.drawLine(81, 134, 99, 120, TFT_YELLOW);
  display.drawLine(239, 134, 221, 120, TFT_YELLOW);
  display.fillCircle(76, 87, 2, TFT_WHITE);
  display.fillCircle(244, 116, 2, TFT_WHITE);
  fillUiEllipse(160, 140, 38, 7, kSettingsLine);

  char path[112]{};
  constexpr int16_t spriteX = 128;
  constexpr int16_t spriteY = 70;
  if (eggHatchVisualStage < 6U) {
    if (eggHatchVisualStage == 0U) {
      std::snprintf(path, sizeof(path), "/pokegochi/assets/firered/ui/egg_hatch_fresh.pkg");
    }
    else if (eggHatchVisualStage == 1U)
      std::snprintf(path, sizeof(path), "/pokegochi/assets/firered/ui/egg_hatch_cracked.pkg");
    else if (eggHatchVisualStage <= 4U)
      std::snprintf(path, sizeof(path), "/pokegochi/assets/firered/ui/egg_hatch_breaking_%u.pkg",
                    static_cast<unsigned>(eggHatchVisualStage - 2U));
    else
      std::snprintf(path, sizeof(path), "/pokegochi/assets/firered/ui/egg_hatch_shell.pkg");
    if (!AssetRenderer::draw(display, path,
        static_cast<int16_t>(spriteX + eggHatchRockOffset), spriteY)) {
      fillUiEllipse(static_cast<int16_t>(160 + eggHatchRockOffset), 103, 21, 28,
                    kBattleFrameShadow);
      fillUiEllipse(static_cast<int16_t>(160 + eggHatchRockOffset), 103, 19, 26,
                    TFT_WHITE);
    }
  } else {
    std::snprintf(path, sizeof(path), "/pokegochi/assets/pokemon/%sfront/%03u.pkg",
                  eggHatchShiny ? "shiny/" : "", eggHatchSpecies);
    if (!AssetRenderer::draw(display, path, 128, 70))
      creature(160, 103, eggHatchSpecies, true, eggHatchShiny);
    if (eggHatchShiny)
      AssetRenderer::draw(display,
          "/pokegochi/assets/firered/battle_anims/sprites/sparkle_1_00.pkg", 218, 55);
  }

  const int16_t messageHeight = eggHatchVisualStage == 6U ? 43 : 64;
  drawGbaInsetPanel(13, 160, 294, messageHeight, 7, kBattleFrameShadow,
                    kSettingsPaper, kBattleFrameGold);
  fireRedText.setTextColor(kBattleInk, kSettingsPaper);
  fireRedText.setTextDatum(MC_DATUM);
  const SpeciesData* species = findSpecies(eggHatchSpecies);
  if (eggHatchVisualStage == 0U) {
    fireRedText.drawStringFitted("OH? THE EGG IS MOVING!", 160, 192, 274, 2);
  } else if (eggHatchVisualStage == 1U) {
    fireRedText.drawStringFitted("CRACKS ARE FORMING...", 160, 192, 274, 2);
  } else if (eggHatchVisualStage <= 4U) {
    fireRedText.drawStringFitted("THE EGG IS HATCHING!", 160, 192, 274, 2);
  } else if (eggHatchVisualStage == 5U) {
    fireRedText.drawString("OH!", 160, 192, 2);
  } else {
    char line[64];
    std::snprintf(line, sizeof(line), "A %s%s HATCHED!",
                  eggHatchShiny ? "SHINY " : "", species ? species->name : "POKEMON");
    fireRedText.drawStringFitted(line, 160, 172, 274, 1);
    display.drawFastHLine(25, 182, 270, kSettingsLine);
    fireRedText.setTextColor(themeDark(), kSettingsPaper);
    std::snprintf(line, sizeof(line), "LV %u  SENT TO BOX",
                  static_cast<unsigned>(eggHatchLevel));
    fireRedText.drawString(line, 160, 193, 1);
    button(95, 207, 130, 26, "CONTINUE", TFT_DARKGREEN);
  }
  fireRedText.setTextDatum(TL_DATUM);
}

void presentEggHatchFrame(int16_t x, int16_t y, int16_t width, int16_t height,
                          uint16_t waitMs) {
  invalidatePixels(x, y, width, height);
  requestRetainedFrame();
  presentRetainedFrame();
  if (waitMs) delay(waitMs);
}

void playEggHatch(uint16_t species, bool shiny, uint8_t level) {
  eggHatchSpecies = species;
  eggHatchShiny = shiny;
  eggHatchLevel = level ? level : 5U;
  eggHatchVisualStage = 0;
  eggHatchRockOffset = 0;
  battleArenaVisible = false;
  screen = Screen::EggHatch;
  presentedScreen = Screen::Diagnostic;

  AssetRenderer::clearCache();
  static constexpr const char* kEggAssets[] = {
      "/pokegochi/assets/firered/ui/egg_hatch_fresh.pkg",
      "/pokegochi/assets/firered/ui/egg_hatch_cracked.pkg",
      "/pokegochi/assets/firered/ui/egg_hatch_breaking_0.pkg",
      "/pokegochi/assets/firered/ui/egg_hatch_breaking_1.pkg",
      "/pokegochi/assets/firered/ui/egg_hatch_breaking_2.pkg",
      "/pokegochi/assets/firered/ui/egg_hatch_shell.pkg"};
  for (const char* asset : kEggAssets) AssetRenderer::preload(asset);
  char pokemonPath[96];
  std::snprintf(pokemonPath, sizeof(pokemonPath), "/pokegochi/assets/pokemon/%sfront/%03u.pkg",
                shiny ? "shiny/" : "", species);
  AssetRenderer::preload(pokemonPath);
  if (shiny)
    AssetRenderer::preload("/pokegochi/assets/firered/battle_anims/sprites/sparkle_1_00.pkg");

  presentEggHatchFrame(0, 0, 320, 240, 650);
  static constexpr int8_t kRock[] = {-4, 4, -6, 6, -7, 7, -5, 5, 0};
  static constexpr uint16_t kRockWait[] = {180, 180, 140, 140, 105, 105, 80, 80, 160};
  for (uint8_t index = 0; index < sizeof(kRock); ++index) {
    eggHatchRockOffset = kRock[index];
    presentEggHatchFrame(92, 48, 136, 109, kRockWait[index]);
  }
  eggHatchVisualStage = 1;
  presentEggHatchFrame(15, 48, 290, 171, 500);
  for (uint8_t stage = 2; stage <= 4; ++stage) {
    eggHatchVisualStage = stage;
    presentEggHatchFrame(15, 48, 290, 171, 190);
  }
  eggHatchVisualStage = 5;
  presentEggHatchFrame(15, 48, 290, 171, 420);
  eggHatchVisualStage = 6;
  eggHatchRockOffset = 0;
  // The reveal deliberately has no timeout. The player must acknowledge the
  // species before Home can offer another regional egg.
  presentEggHatchFrame(0, 48, 320, 192, 0);
}

void drawGymInvite(){
  const GymId gymId=GymSystem::next(gameSave.gymProgress);
  const GymDefinition* gym=GymSystem::definition(gymId);
  if(!gym||!gymChallengeAvailable()){screen=Screen::Home;drawHome();return;}
  const uint8_t gymIndex=static_cast<uint8_t>(gymId);
  const uint8_t regionalGym=static_cast<uint8_t>(gymIndex%8U+1U);
  const char* region=gymIndex<8U?"KANTO":gymIndex<16U?"JOHTO":"HOENN";
  uint8_t low=gym->team[0].level,high=gym->team[0].level;
  for(uint8_t i=1;i<gym->teamSize;++i){
    if(gym->team[i].level<low)low=gym->team[i].level;
    if(gym->team[i].level>high)high=gym->team[i].level;
  }

  beginScreenPresentation(Screen::GymInvite,themePale());
  drawFireRedBattleWindow(4,4,312,232,themeAccent(),TFT_WHITE);
  drawFireRedBattleWindow(9,9,302,38,themeAccent(),themePrimary());
  fireRedText.setTextColor(TFT_WHITE,themePrimary());
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawString("GYM CHALLENGE",160,28,2);

  // Leader card. Every regional leader portrait and badge is already part
  // of the SD pack, so the invitation uses the original game art instead
  // of a generic challenge panel.
  drawFireRedBattleWindow(11,50,94,137,themeAccent(),themePale());
  fireRedText.setTextColor(themeDark(),themePale());
  fireRedText.drawString("LEADER",58,62,1);
  fireRedText.setTextDatum(TL_DATUM);
  char assetPath[96];
  std::snprintf(assetPath,sizeof(assetPath),"/pokegochi/assets/trainers/%s.pkg",gym->frontAsset);
  if(!sdReady||!AssetRenderer::draw(display,assetPath,26,70)){
    display.fillCircle(58,89,12,themePrimary());
    display.fillRoundRect(40,103,36,29,8,themePrimary());
  }
  fireRedText.setTextColor(TFT_BLACK,themePale());
  fireRedText.drawStringFitted(gym->leader,17,141,82,1);
  std::snprintf(assetPath,sizeof(assetPath),
                "/pokegochi/assets/firered/trainer_card/badge_%u.pkg",
                static_cast<unsigned>(gymIndex));
  AssetRenderer::draw(display,assetPath,19,163);
  fireRedText.drawStringFitted(gym->badge,40,165,58,1);

  // Compact FireRed-style challenge card: the important rules are visible
  // at a glance, with the irrelevant VS Seeker warning deliberately gone.
  drawFireRedBattleWindow(108,50,201,137,themeAccent(),TFT_WHITE);
  display.fillRect(114,56,189,20,themePrimary());
  char line[48];
  std::snprintf(line,sizeof(line),"%s  GYM %u/8",region,regionalGym);
  fireRedText.setTextColor(TFT_WHITE,themePrimary());
  fireRedText.drawStringFitted(line,118,61,181,1);
  fireRedText.setTextColor(TFT_BLACK,TFT_WHITE);
  std::snprintf(line,sizeof(line),"%s BADGE",gym->badge);
  fireRedText.drawStringFitted(line,116,82,185,2);
  fireRedText.drawString("3 BATTLES IN A ROW",120,108,1);
  std::snprintf(line,sizeof(line),"TEAM LEADER: %s",gym->type);
  fireRedText.drawStringFitted(line,120,126,177,1);
  std::snprintf(line,sizeof(line),"TEAM LEVELS: %u-%u",low,high);
  fireRedText.drawStringFitted(line,120,144,177,1);

  // Three connected Poké Balls make the consecutive-battle structure clear
  // without adding another explanatory sentence to the small screen.
  constexpr int16_t markerY=169;
  display.drawFastHLine(151,markerY,108,TFT_DARKGREY);
  for(uint8_t i=0;i<3;++i){
    const int16_t markerX=142+54*i;
    display.fillCircle(markerX,markerY,9,TFT_WHITE);
    display.fillCircle(markerX,markerY-2,7,TFT_RED);
    display.fillRect(markerX-7,markerY-2,15,3,TFT_DARKGREY);
    display.fillCircle(markerX,markerY,3,TFT_WHITE);
    display.drawCircle(markerX,markerY,9,TFT_DARKGREY);
  }
  fireRedText.setTextDatum(TL_DATUM);
  button(18,194,136,34,"CHALLENGE",TFT_DARKGREEN);button(166,194,136,34,"LATER",TFT_RED);
}

