void refreshBattlePartySelection() {
  // There are only three party cards; repainting this contained list is much
  // cheaper than clearing the screen and leaves the header perfectly still.
  for (uint8_t slot = 0; slot < kPartyCapacity; ++slot) drawBattlePartyRow(slot);
  display.fillRect(0, 199, 320, 41, TFT_LIGHTGREY);
  if (battlePartySelection >= 0) {
    button(12, 202, 88, 31, "SHIFT", TFT_DARKGREEN);
    button(116, 202, 88, 31, "SUMMARY", themePrimary());
    if (!forcedBattleSwitch) button(220, 202, 88, 31, "CANCEL", TFT_RED);
  } else if (!forcedBattleSwitch) button(110, 202, 100, 31, "CANCEL", TFT_RED);
}

const char* pokemonTypeName(PokemonType type) {
  static constexpr const char* names[] = {"NORMAL", "FIGHTING", "FLYING", "POISON", "GROUND", "ROCK",
      "BUG", "GHOST", "STEEL", "FIRE", "WATER", "GRASS", "ELECTRIC", "PSYCHIC", "ICE", "DRAGON", "DARK", "FAIRY"};
  const uint8_t index = static_cast<uint8_t>(type);
  return index < sizeof(names) / sizeof(names[0]) ? names[index] : "NORMAL";
}

uint16_t pokemonTypeColor(PokemonType type) {
  // FireRed type-label palette, translated to RGB565. The same semantic
  // colours are shared by Summary and Battle so type is readable at a glance.
  static constexpr uint16_t colors[] = {
      0xAD55, // NORMAL
      0xC986, // FIGHTING
      0xA47D, // FLYING
      0xA30D, // POISON
      0xE5CB, // GROUND
      0xBDCB, // ROCK
      0xA5A5, // BUG
      0x7353, // GHOST
      0xBDF7, // STEEL
      0xF249, // FIRE
      0x6C5E, // WATER
      0x7E8A, // GRASS
      0xFE05, // ELECTRIC
      0xF34F, // PSYCHIC
      0x9F3E, // ICE
      0x72F9, // DRAGON
      0x7AEB, // DARK
      0xF59D  // FAIRY
  };
  const uint8_t index = static_cast<uint8_t>(type);
  return index < sizeof(colors) / sizeof(colors[0]) ? colors[index] : colors[0];
}

uint16_t pokemonTypeTextColor(PokemonType type) {
  return type == PokemonType::Electric || type == PokemonType::Ice ||
         type == PokemonType::Ground || type == PokemonType::Steel
      ? TFT_DARKGREY : TFT_WHITE;
}

void drawPokemonTypeBadge(PokemonType type, int16_t x, int16_t y,
                          int16_t width, int16_t height) {
  const uint16_t fill = pokemonTypeColor(type);
  display.fillRoundRect(x, y, width, height, 4, TFT_DARKGREY);
  display.fillRoundRect(x + 2, y + 2, width - 4, height - 4, 3, fill);
  fireRedText.setTextColor(pokemonTypeTextColor(type), fill);
  fireRedText.setTextDatum(MC_DATUM);
  fireRedText.drawStringAuto(pokemonTypeName(type), x + width / 2, y + height / 2, width - 8);
  fireRedText.setTextDatum(TL_DATUM);
}

