void drawCompactSummaryPokemonCard(const OwnedPokemon& pokemon) {
  // FireRed reserves the whole left half for the Pokemon even though its
  // front sprite is only 64x64. On the 320x240 touch layout that became a
  // conspicuous empty box. Keep the original sprite and palette, but contain
  // them in a smaller, centred card below the level/name line.
  constexpr uint16_t kOuter = 0x6B6D;
  constexpr uint16_t kPaper = 0xFFDF;
  constexpr uint16_t kPattern = 0xE73C;
  display.fillRoundRect(31, 50, 96, 80, 6, kOuter);
  display.fillRoundRect(33, 52, 92, 76, 5, 0xD69A);
  display.fillRoundRect(35, 54, 88, 72, 3, kPaper);
  // A restrained checker pattern echoes the original Summary background and
  // gives pale species a silhouette without a harsh flat sprite rectangle.
  for (int16_t y = 58; y < 124; y += 8)
    for (int16_t x = 39 + ((y / 8) & 1) * 4; x < 121; x += 8)
      display.fillRect(x, y, 2, 2, kPattern);
  drawSummaryPicture(pokemon, 47, 58);
  if (pokemon.shiny) {
    display.fillCircle(117, 119, 6, 0xFD60);
    display.drawFastHLine(113, 119, 9, TFT_WHITE);
    display.drawFastVLine(117, 115, 9, TFT_WHITE);
    display.drawPixel(115, 117, TFT_WHITE);
    display.drawPixel(119, 121, TFT_WHITE);
  }
}

