  display.fillRoundRect(x, 180, width, 27, 4, kFrame);
  display.fillRect(x + 3, 183, width - 6, 21, fill);
  fireRedText.setTextColor(enabled ? TFT_DARKGREY : TFT_LIGHTGREY, fill);
  fireRedText.setTextDatum(MC_DATUM);
