void drawSummaryEvControls(bool editable) {
  char step[18]; std::snprintf(step, sizeof(step), "STEP %u", summaryEvStep);
  drawSummaryEvButton(7, 55, "ZERO", editable && summaryEvAt(summaryEvDraft, summaryEvSelected));
  drawSummaryEvButton(65, 45, "-", editable && summaryEvAt(summaryEvDraft, summaryEvSelected));
  drawSummaryEvButton(113, 94, step, editable);
  drawSummaryEvButton(210, 45, "+", editable && summaryEvFree &&
      summaryEvAt(summaryEvDraft, summaryEvSelected) < CollectionLogic::kMaximumEffortValue);
  drawSummaryEvButton(258, 55, "MAX", editable && summaryEvFree &&
      summaryEvAt(summaryEvDraft, summaryEvSelected) < CollectionLogic::kMaximumEffortValue);
}

