    case Screen::Diagnostic: drawDiagnostic(); break;
    case Screen::OakIntro: drawOakIntro(); break;
    case Screen::Starter: drawStarter(); break;
    case Screen::RegionalDiscovery: drawRegionalDiscovery(); break;
