    case Screen::Settings: drawSettings(); break;
    case Screen::PlayerStats: drawPlayerStats(); break;
    case Screen::WirelessUpdate: drawWirelessUpdate(); break;
    case Screen::EggOffer: drawEggOffer(); break;
    case Screen::EggStatus: drawEggStatus(); break;
    case Screen::EggHatch: drawEggHatch(); break;
    case Screen::GymInvite: drawGymInvite(); break;
    case Screen::LeagueInvite: drawLeagueInvite(); break;
    case Screen::MegaChallengeInvite: drawMegaChallengeInvite(); break;
    case Screen::TowerInvite: drawTowerInvite(); break;
    case Screen::LeagueComplete: drawLeagueComplete(); break;
    case Screen::ChooseBattler: drawChooseBattler(); break;
    case Screen::TrainerIntro: drawTrainerIntro(); break;
    case Screen::Battle: drawBattle(); break;
    case Screen::MoveSelect: drawMoveSelect(); break;
    case Screen::EvolutionCinematic: drawEvolutionCinematic(); break;
    case Screen::TradeCinematic: drawTradeCinematic(); break;
    case Screen::EvolutionChoose: drawEvolutionChoose(); break;
    case Screen::MoveLearn: drawMoveLearn(); break;
    case Screen::BattleParty: drawBattleParty(); break;
